/**
 * The admin "Automata" section: machines, stage type maps and a simulator.
 * Everything is generated by @plobi/core from the same code the engine runs.
 */
import { Type, type FastifyPluginAsyncTypebox } from '@fastify/type-provider-typebox';
import {
  describeMachines,
  evaluateTrip,
  insertTransits,
  materializeInstructions,
  materializeRequirements,
  phaseDiagram,
  PROFILES,
  stageStateDiagram,
  stageTypeMap,
  tripStateDiagram,
  type EventInput,
  type StageInput,
} from '@plobi/core';
import { notFound } from '../../platform/errors.js';
import { currentUser, requireRole } from '../../platform/http.js';
import type { CatalogService } from '../catalog/service.js';

const SimulateBody = Type.Object({
  tags: Type.Optional(Type.Array(Type.String())),
  customerId: Type.Optional(Type.String()),
  /** Points only; transits, requirements and instructions are added like for a real trip. */
  stages: Type.Array(
    Type.Object({ id: Type.String(), typeCode: Type.String(), tags: Type.Optional(Type.Array(Type.String())) }),
    { minItems: 1 },
  ),
  events: Type.Array(Type.Record(Type.String(), Type.Unknown())),
});

export function automataRoutes(catalog: CatalogService): FastifyPluginAsyncTypebox {
  return async (app) => {
    app.get('/state-machines', { schema: { tags: ['automata'] } }, async (req) => {
      currentUser(req);
      return {
        ...describeMachines(),
        diagrams: {
          stageState: stageStateDiagram(),
          tripState: tripStateDiagram(),
          profiles: Object.fromEntries(PROFILES.map((p) => [p, phaseDiagram(p)])),
        },
      };
    });

    app.get(
      '/stage-types/:code/map',
      { schema: { tags: ['automata'], params: Type.Object({ code: Type.String() }) } },
      async (req) => {
        requireRole(req, 'admin', 'dispatcher');
        const map = stageTypeMap(await catalog.get(), req.params.code);
        if (!map) throw notFound('Stage type', req.params.code);
        const labels = new Map(map.transitions.map((t) => [`${t.from}>${t.to}`, t.automatic ? 'auto' : t.events.map((e) => e.code).join(' / ')]));
        return { ...map, diagram: phaseDiagram(map.stageType.profile, (from, to) => labels.get(`${from}>${to}`)) };
      },
    );

    /** Runs a trip and events through the engine without storing anything. */
    app.post('/simulate', { schema: { tags: ['automata'], body: SimulateBody } }, async (req) => {
      requireRole(req, 'admin', 'dispatcher');
      const cat = await catalog.get();
      const trip = { tags: req.body.tags ?? [], ...(req.body.customerId ? { customerId: req.body.customerId } : {}) };
      const stages: StageInput[] = insertTransits(req.body.stages, cat).map((s) =>
        cat.stageTypes[s.typeCode]?.kind === 'point'
          ? { ...s, requirements: materializeRequirements(s, trip, cat), instructions: materializeInstructions(s, trip, cat) }
          : s,
      );
      return evaluateTrip({ id: 'simulation', ...trip, stages }, req.body.events as unknown as EventInput[], cat);
    });
  };
}
